import userStore from '@/store/userStore';


/**
 * 判断是否存在权限
 */
export const isPermission = (key: string) => {
    return userStore.permissions[key];
}

/**
 * 权限判断
 * @param keys 权限列表
 * @param type or | and  权限类型
 */
export const isPermissions = (keys: string[], type: "or" | "and" = "or") => {

    if(type == 'or'){
        return keys.some((key) => userStore.permissions[key]);
    }else {
        return keys.every((key) => userStore.permissions[key]);
    }
}